def compute(vars):
    old = vars["v1"]
    new = vars["v2"]

    if old == 0:
        return {"value": None, "trace": {"output_meta": {"currency": None, "scale": "ones", "unit": "percentage"}}}

    change_ratio = (new - old) / old
    percentage_increase = change_ratio * 100

    return {
        "value": percentage_increase,
        "trace": {
            "old": old,
            "new": new,
            "change_ratio": change_ratio,
            "output_meta": {"currency": None, "scale": "ones", "unit": "percentage"},
        },
    }
